package com.mohymods.kingdomsmp.equipment;
import com.mohymods.kingdomsmp.economy.*;
import com.mohymods.kingdomsmp.network.*;
import com.mohymods.kingdomsmp.placement.PlacementProtection;
import net.minecraft.core.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.nbt.ListTag;
import net.minecraft.server.level.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.enchantment.*;
import net.minecraft.tags.EnchantmentTags;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.network.chat.Component;
import java.util.*;
import java.io.IOException;
/** Royal Gilded workstation UI reuses the existing authenticated commerce protocol, not chest slots. */
public final class MasterStationService {
 private record Station(ServerLevel level,BlockPos position,MasterGear gear){ }
 private record Quote(UUID id,long revision,long issued,List<ItemStack> before,List<ItemStack> after,int xp,int levels,float progress,int total,String selected,String text){ }
 private static final Map<ServerPlayer,Station> STATIONS=new WeakHashMap<>();
 private static final Map<ServerPlayer,Quote> QUOTES=new WeakHashMap<>();
 private MasterStationService(){ }
 public static boolean active(ServerPlayer p){return STATIONS.containsKey(p);}
 public static void close(ServerPlayer p){STATIONS.remove(p);QUOTES.remove(p);}
 public static void open(ServerPlayer p,BlockPos pos,MasterGear gear){try{close(p);STATIONS.put(p,new Station(p.serverLevel(),pos.immutable(),gear));require(p);CommerceNetworking.open(p,7);}catch(RuntimeException invalid){close(p);p.sendSystemMessage(Component.literal(invalid.getMessage()));}}
 private static Station require(ServerPlayer p){var st=STATIONS.get(p);if(!com.mohymods.kingdomsmp.kingdom.AlphaScope.destinationAvailable(com.mohymods.kingdomsmp.contribution.ContributionService.kingdom(p.server).attainedTier(),p.serverLevel().dimension().location().toString())||st==null||p.serverLevel()!=st.level()||!p.isAlive()||p.isSpectator()||p.isCreative()||p.server.getPlayerList().getPlayer(p.getUUID())!=p||!st.level().hasChunkAt(st.position())||p.distanceToSqr(st.position().getCenter())>64||p.containerMenu!=p.inventoryMenu||!p.containerMenu.getCarried().isEmpty()||!st.level().getBlockState(st.position()).is(st.gear()==MasterGear.EXTRACTION?MasterGearItems.EXTRACTION.get():MasterGearItems.CODEX.get()))throw new IllegalStateException("Use the actual nearby workstation in Survival with containers closed");String denial=PlacementProtection.check(st.level(),p,st.position(),st.position());if(denial!=null)throw new IllegalStateException(denial);return st;}
 public static void review(ServerPlayer p,String selected)throws IOException{var st=require(p);var s=CommerceService.store(p.server);CommerceService.verifyReceipt(p,s);var rules=MasterGearRules.get(p.server);var before=MasterWorkTransaction.inventory(p);var source=before.get(0);MasterEnchanting.Result result;if(st.gear()==MasterGear.EXTRACTION){if(!selected.startsWith("station:extract:"))throw new IllegalArgumentException("Select an actual enchantment");var id=ResourceLocation.parse(selected.substring(16));var holder=p.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(net.minecraft.resources.ResourceKey.create(Registries.ENCHANTMENT,id));result=MasterEnchanting.extract(source,holder,rules.extractionXp());}else{if(!selected.equals("station:combine"))throw new IllegalArgumentException("Unknown Codex work");result=MasterEnchanting.combine(source,before.get(1),rules.codexMaxCost(),rules.codexMaxLevel());}
  if(p.experienceLevel<result.cost())throw new IllegalStateException("Requires "+result.cost()+" XP levels");var after=new ArrayList<>(before.stream().map(ItemStack::copy).toList());after.set(0,ItemStack.EMPTY);if(st.gear()==MasterGear.CODEX)after.set(1,ItemStack.EMPTY);var inputs=new HashMap<Item,Integer>();inputs.put(Items.LAPIS_LAZULI,rules.lapisCost());if(st.gear()==MasterGear.EXTRACTION)inputs.put(Items.BOOK,1);after=new ArrayList<>(com.mohymods.kingdomsmp.profession.FarmerInventoryExchange.plan(after,inputs,Map.of()));insert(after,result.equipment());if(!result.book().isEmpty())insert(after,result.book());String text=st.gear().title()+": "+changes(source,result.equipment())+" Spend exactly "+result.cost()+" XP levels, "+rules.lapisCost()+" lapis and "+(st.gear()==MasterGear.EXTRACTION?"one blank book":"the reviewed enchanted book")+". Source and every output commit together; all other item data and durability are preserved. "+(st.gear()==MasterGear.CODEX?"Native compatibility is mandatory. Equal legitimate books may advance one level beyond the native maximum, within configured limits.":"Only the selected enchantment is removed. Curses/signature gear cannot be extracted.");QUOTES.put(p,new Quote(UUID.randomUUID(),s.revision(),System.nanoTime(),before,List.copyOf(after),result.cost(),p.experienceLevel,p.experienceProgress,p.totalExperience,selected,text));
 }
 private static String changes(ItemStack before,ItemStack after){var old=EnchantmentHelper.getEnchantmentsForCrafting(before);var next=EnchantmentHelper.getEnchantmentsForCrafting(after);var all=new HashSet<net.minecraft.core.Holder<Enchantment>>();all.addAll(old.keySet());all.addAll(next.keySet());var text=new StringBuilder();for(var enchant:all.stream().sorted(Comparator.comparing(e->e.unwrapKey().orElseThrow().location().toString())).toList()){int a=old.getLevel(enchant),b=next.getLevel(enchant);if(a==b)continue;String name=Enchantment.getFullname(enchant,Math.max(1,b==0?a:b)).getString();if(name.length()>60)name=name.substring(0,60);String change=name+" ["+a+" -> "+(b==0?"book; removed from source":Integer.toString(b))+"]; ";if(text.length()+change.length()>240){text.append("additional compatible changes; ");break;}text.append(change);}return text.toString();}
 private static void insert(List<ItemStack> after,ItemStack item){for(int i=0;i<36;i++)if(after.get(i).isEmpty()){after.set(i,item.copy());return;}throw new IllegalStateException("Make room for every output before confirming");}
 public static String confirm(ServerPlayer p,UUID nonce)throws IOException{var st=require(p);var q=QUOTES.remove(p);var s=CommerceService.store(p.server);if(q==null||!q.id().equals(nonce)||q.revision()!=s.revision()||System.nanoTime()-q.issued()>30_000_000_000L||!MasterWorkTransaction.same(q.before(),MasterWorkTransaction.inventory(p))||q.levels()!=p.experienceLevel||q.total()!=p.totalExperience||Float.compare(q.progress(),p.experienceProgress)!=0)throw new IllegalStateException("Workstation review changed or expired");review(p,q.selected());var check=QUOTES.remove(p);if(check.xp()!=q.xp()||!MasterWorkTransaction.same(check.after(),q.after()))throw new IllegalStateException("Native enchantment/configuration changed");MasterWorkTransaction.commit(p,q.id(),st.gear(),q.before(),q.after(),q.xp(),new ListTag());return st.gear().title()+" completed once. Outputs are in your inventory.";}
 public static CommerceView handle(ServerPlayer p,CommerceRequest request)throws IOException{String notice="";if(request.action()==0)QUOTES.remove(p);else if(request.action()==1)review(p,request.selected());else if(request.action()==2)notice=confirm(p,request.review());else throw new IllegalArgumentException("Invalid workstation action");return view(p,request.requestId(),notice);}
 public static CommerceView view(ServerPlayer p,long request,String notice){var st=require(p);var s=CommerceService.store(p.server);List<CommerceView.Entry> rows=new ArrayList<>();rows.add(new CommerceView.Entry("station:help",st.gear().title(),"Put equipment in hotbar slot 1. Codex: one enchanted book in slot 2. Keep lapis and blank books elsewhere. Review exact outputs and XP before confirming. Trading and use by any player is allowed.",0,"INFO"));if(st.gear()==MasterGear.EXTRACTION){var enchants=EnchantmentHelper.getEnchantmentsForCrafting(p.getInventory().getItem(0));for(var e:enchants.entrySet().stream().sorted(Comparator.comparing(v->v.getKey().unwrapKey().orElseThrow().location().toString())).limit(32).toList())if(!e.getKey().is(EnchantmentTags.CURSE))rows.add(new CommerceView.Entry("station:extract:"+e.getKey().unwrapKey().orElseThrow().location(),Enchantment.getFullname(e.getKey(),e.getIntValue()).getString(),"Transfer only this enchantment to a real blank book. Original equipment, other enchantments and durability remain. XP and lapis required.",0,"MASTER_SERVICE"));}else rows.add(new CommerceView.Entry("station:combine","Combine / advance enchantments","One legitimate compatible book is consumed. Half native-style XP cost; configured higher cost ceiling. Two equal maximums can improve one level. No incompatible/free enchantments.",0,"MASTER_SERVICE"));var q=QUOTES.get(p);return new CommerceView(request,s.revision(),false,7,com.mohymods.kingdomsmp.contribution.ContributionService.kingdom(p.server).attainedTier(),s.balance(p.getUUID()),rows,q==null?CommerceRequest.NONE:q.id(),q==null?"":q.text(),notice.isBlank()?st.gear().title():notice);}
}
